def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        email = email if valid_email(email) else ""
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
        })

    # Build connected components using email and phone+last-name match keys.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    seen = {}
    for i, row in enumerate(prepared):
        keys = []
        if row["email"]:
            keys.append(("email", row["email"]))
        if row["phone"] and row["last_name"]:
            keys.append(("phone_last", row["phone"], row["last_name"].lower()))
        for key in keys:
            if key in seen:
                union(i, seen[key])
            else:
                seen[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    output = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        def pick(field, require_valid=False):
            candidates = [
                row for row in group
                if row[field] and (not require_valid or row[field])
            ]
            if not candidates:
                return ""
            chosen = min(
                candidates,
                key=lambda row: (
                    row["source"] != "manual",
                    -row["updated_dt"].timestamp(),
                    row["index"],
                ),
            )
            return chosen[field]

        latest = max(row["updated_dt"] for row in group)
        output.append({
            "first_name": pick("first_name"),
            "last_name": pick("last_name"),
            "zip": pick("zip"),
            "email": pick("email", require_valid=True),
            "phone": pick("phone", require_valid=True),
            "source": pick("source"),
            "tags": ";".join(sorted(set().union(*(row["tags"] for row in group)))),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
